import openpyxl
from openpyxl.styles import Font
N = 4
ws = openpyxl.Workbook().active
for i in range(1, N + 1):
    ws.cell(row=1, column=i + 1, value=i).font = Font(bold=True)
    ws.cell(row=i + 1, column=1, value=i).font = Font(bold=True)
    for j in range(1, N + 1):
        ws.cell(row=i + 1, column=j + 1, value=i * j)
for row in ws.iter_rows(values_only=True): print(row)
